function(container, apiUrl, tables) {
  // データ取得と初期化
  async function loadDashboardData() {
    try {
      const projects = await window.aivicApi.list(0) || tables[0]?.records || [];

      // KPI計算
      const total = projects.length;
      const active = projects.filter(p => p.status === '進行中' || p.status === '開始').length;
      const completed = projects.filter(p => p.status === '完了').length;
      const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;
      const totalBudget = projects.reduce((sum, p) => sum + (parseFloat(p.budget) || 0), 0);

      // KPI表示更新
      container.querySelector('#kpi-total').textContent = total;
      container.querySelector('#kpi-active').textContent = active;
      container.querySelector('#kpi-completion').textContent = completionRate + '%';
      container.querySelector('#kpi-budget').textContent = '¥' + totalBudget.toLocaleString();
      container.querySelector('#kpi-active-ratio').textContent = total > 0 ? Math.round((active / total) * 100) + '%' : '0%';

      // 月別進捗チャート
      const monthlyData = {};
      projects.forEach(p => {
        if (p.created_at) {
          const month = p.created_at.slice(0, 7); // YYYY-MM
          monthlyData[month] = (monthlyData[month] || 0) + 1;
        }
      });

      const sortedMonths = Object.keys(monthlyData).sort().slice(-6);
      const monthlyValues = sortedMonths.map(m => monthlyData[m] || 0);

      const progressCtx = container.querySelector('#progress-chart').getContext('2d');
      new Chart(progressCtx, {
        type: 'line',
        data: {
          labels: sortedMonths.map(m => m.slice(5) + '月'),
          datasets: [{
            label: 'プロジェクト数',
            data: monthlyValues,
            borderColor: '#22c55e',
            backgroundColor: 'rgba(34, 197, 94, 0.1)',
            borderWidth: 2,
            fill: true,
            tension: 0.3
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false }
          },
          scales: {
            y: { beginAtZero: true }
          }
        }
      });

      // ステータス分布チャート
      const statusCounts = {};
      projects.forEach(p => {
        const status = p.status || '未設定';
        statusCounts[status] = (statusCounts[status] || 0) + 1;
      });

      const statusCtx = container.querySelector('#status-chart').getContext('2d');
      new Chart(statusCtx, {
        type: 'doughnut',
        data: {
          labels: Object.keys(statusCounts),
          datasets: [{
            data: Object.values(statusCounts),
            backgroundColor: ['#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6']
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { position: 'bottom', labels: { fontSize: 12 } }
          }
        }
      });

      // 要対応項目
      const priorityItems = projects
        .filter(p => p.status === '遅延' || p.priority === '高' || (p.deadline && new Date(p.deadline) < new Date(Date.now() + 7*24*60*60*1000)))
        .slice(0, 5);

      const priorityHtml = priorityItems.length > 0 
        ? priorityItems.map(item => `
          <div style="padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
            <div style="font-size: 13px; font-weight: 500; color: var(--text);">${item.name || 'プロジェクト'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
              ${item.status || '状態不明'} • ${item.deadline ? '期限: ' + item.deadline : '期限未設定'}
            </div>
          </div>
        `).join('')
        : '<div style="font-size: 13px; color: var(--text-muted); text-align: center; padding: 20px 0;">対応が必要な項目はありません</div>';

      container.querySelector('#priority-actions').innerHTML = priorityHtml;

      // 最新更新
      const recentUpdates = projects
        .sort((a, b) => new Date(b.updated_at || b.created_at || 0) - new Date(a.updated_at || a.created_at || 0))
        .slice(0, 4);

      const updatesHtml = recentUpdates.length > 0
        ? recentUpdates.map(item => `
          <div style="padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
            <div style="font-size: 13px; font-weight: 500; color: var(--text);">${item.name || 'プロジェクト'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
              ${item.updated_at ? new Date(item.updated_at).toLocaleDateString() : '更新日不明'} • ${item.status || '状態不明'}
            </div>
          </div>
        `).join('')
        : '<div style="font-size: 13px; color: var(--text-muted); text-align: center; padding: 20px 0;">最近の更新はありません</div>';

      container.querySelector('#recent-updates').innerHTML = updatesHtml;

      // 通知カウント
      const urgentCount = projects.filter(p => 
        p.status === '遅延' || 
        (p.deadline && new Date(p.deadline) < new Date(Date.now() + 3*24*60*60*1000))
      ).length;

      container.querySelector('#notification-count').textContent = urgentCount;
      if (urgentCount > 0) {
        container.querySelector('#notification-content').textContent = 
          `${urgentCount}件の緊急対応が必要なプロジェクトがあります。`;
      }

    } catch (error) {
      console.error('Dashboard data loading failed:', error);
      // エラー時は初期データで表示
      const fallbackData = tables[0]?.records || [];
      container.querySelector('#kpi-total').textContent = fallbackData.length;
    }
  }

  // 初期データ読み込み
  loadDashboardData();

  // 定期更新（5分間隔）
  setInterval(loadDashboardData, 5 * 60 * 1000);
}

function(container, apiUrl, tables) {
  let currentData = [];
  let filteredData = [];
  let currentPage = 1;
  let pageSize = 20;

  // ステータスバッジの色を取得
  function getStatusBadge(status) {
    const badges = {
      'draft': { bg: 'rgba(156, 163, 175, 0.2)', text: '#9CA3AF', label: '下書き' },
      'active': { bg: 'rgba(34, 197, 94, 0.2)', text: '#22C55E', label: '募集中' },
      'in_progress': { bg: 'rgba(59, 130, 246, 0.2)', text: '#3B82F6', label: '進行中' },
      'completed': { bg: 'rgba(168, 85, 247, 0.2)', text: '#A855F7', label: '完了' },
      'cancelled': { bg: 'rgba(239, 68, 68, 0.2)', text: '#EF4444', label: '中止' }
    };
    const badge = badges[status] || badges['draft'];
    return `<span style="background: ${badge.bg}; color: ${badge.text}; padding: 2px 8px; border-radius: 12px; font-size: 12px; font-weight: 500;">${badge.label}</span>`;
  }

  // フェーズバッジの色を取得
  function getPhaseBadge(phase) {
    const badges = {
      'planning': { bg: 'rgba(245, 158, 11, 0.2)', text: '#F59E0B', label: '企画' },
      'design': { bg: 'rgba(139, 92, 246, 0.2)', text: '#8B5CF6', label: '設計' },
      'development': { bg: 'rgba(34, 197, 94, 0.2)', text: '#22C55E', label: '開発' },
      'testing': { bg: 'rgba(59, 130, 246, 0.2)', text: '#3B82F6', label: 'テスト' },
      'deployment': { bg: 'rgba(168, 85, 247, 0.2)', text: '#A855F7', label: 'リリース' }
    };
    const badge = badges[phase] || badges['planning'];
    return `<span style="background: ${badge.bg}; color: ${badge.text}; padding: 2px 8px; border-radius: 12px; font-size: 12px; font-weight: 500;">${badge.label}</span>`;
  }

  // 予算をフォーマット
  function formatBudget(budget) {
    if (!budget) return '-';
    const num = parseInt(budget);
    if (num >= 10000000) return `${Math.floor(num / 10000000)}億${Math.floor((num % 10000000) / 10000)}万円`;
    if (num >= 10000) return `${Math.floor(num / 10000)}万円`;
    return `${num.toLocaleString()}円`;
  }

  // 日付をフォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return `${date.getFullYear()}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getDate().toString().padStart(2, '0')}`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#projects-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center py-8 text-[var(--text-muted)]">該当する案件が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id || ''}" class="border-b border-[var(--border)] hover:bg-rgba(255,255,255,0.02) cursor-pointer">
        <td class="py-3 px-4">
          <div class="font-medium text-[var(--text)]">${row.project_name || row.name || ''}</div>
          <div class="text-sm text-[var(--text-muted)] mt-1">${row.client_name || row.client || ''}</div>
        </td>
        <td class="py-3 px-4 text-[var(--text)]">${formatBudget(row.budget)}</td>
        <td class="py-3 px-4">
          <div class="text-sm text-[var(--text)]">${row.tech_stack || row.technology || ''}</div>
        </td>
        <td class="py-3 px-4">${getPhaseBadge(row.phase)}</td>
        <td class="py-3 px-4 text-[var(--text)]">${formatDate(row.deadline)}</td>
        <td class="py-3 px-4">${getStatusBadge(row.status)}</td>
        <td class="py-3 px-4 text-[var(--text-muted)] text-sm">${formatDate(row.created_at)}</td>
        <td class="py-3 px-4 text-center">
          <div class="flex items-center justify-center gap-2">
            <button class="action-btn secondary edit-btn" data-id="${row.id || ''}" style="font-size: 12px; padding: 4px 8px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${row.id || ''}" style="font-size: 12px; padding: 4px 8px;">削除</button>
          </div>
        </td>
      </tr>
    `).join('');

    // 結果件数を更新
    container.querySelector('#result-count').textContent = `${rows.length}件`;
    updatePagination();
  }

  // ページネーション更新
  function updatePagination() {
    const totalItems = filteredData.length;
    const totalPages = Math.ceil(totalItems / pageSize);
    const startItem = (currentPage - 1) * pageSize + 1;
    const endItem = Math.min(currentPage * pageSize, totalItems);

    container.querySelector('#page-info').textContent = `${startItem}-${endItem}件 / 全${totalItems}件`;
    container.querySelector('#current-page').textContent = currentPage;

    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');

    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  // データフィルタリング
  function filterData() {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const scale = container.querySelector('#filter-scale').value;
    const phase = container.querySelector('#filter-phase').value;
    const tech = container.querySelector('#filter-tech').value;
    const status = container.querySelector('#filter-status').value;

    filteredData = currentData.filter(row => {
      // キーワード検索
      if (keyword && !JSON.stringify(row).toLowerCase().includes(keyword)) return false;

      // 規模フィルタ
      if (scale) {
        const budget = parseInt(row.budget || 0);
        if (scale === 'small' && budget >= 5000000) return false;
        if (scale === 'medium' && (budget < 5000000 || budget >= 20000000)) return false;
        if (scale === 'large' && budget < 20000000) return false;
      }

      // フェーズフィルタ
      if (phase && row.phase !== phase) return false;

      // 技術スタックフィルタ
      if (tech && !(row.tech_stack || '').toLowerCase().includes(tech)) return false;

      // ステータスフィルタ
      if (status && row.status !== status) return false;

      return true;
    });

    // ソート適用
    applySorting();

    // ページネーションリセット
    currentPage = 1;

    // 表示更新
    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    renderRows(filteredData.slice(startIndex, endIndex));
  }

  // ソート適用
  function applySorting() {
    const sortOrder = container.querySelector('#sort-order').value;

    filteredData.sort((a, b) => {
      switch (sortOrder) {
        case 'created_desc':
          return new Date(b.created_at || 0) - new Date(a.created_at || 0);
        case 'created_asc':
          return new Date(a.created_at || 0) - new Date(b.created_at || 0);
        case 'budget_desc':
          return (parseInt(b.budget) || 0) - (parseInt(a.budget) || 0);
        case 'budget_asc':
          return (parseInt(a.budget) || 0) - (parseInt(b.budget) || 0);
        case 'deadline_desc':
          return new Date(b.deadline || 0) - new Date(a.deadline || 0);
        case 'deadline_asc':
          return new Date(a.deadline || 0) - new Date(b.deadline || 0);
        default:
          return 0;
      }
    });
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['案件名', 'クライアント', '予算', '技術要件', 'フェーズ', '納期', 'ステータス', '作成日'];
    const csvData = [headers.join(',')];

    filteredData.forEach(row => {
      const csvRow = [
        `"${(row.project_name || row.name || '').replace(/"/g, '""')}"`,
        `"${(row.client_name || row.client || '').replace(/"/g, '""')}"`,
        row.budget || '',
        `"${(row.tech_stack || row.technology || '').replace(/"/g, '""')}"`,
        row.phase || '',
        row.deadline || '',
        row.status || '',
        row.created_at || ''
      ];
      csvData.push(csvRow.join(','));
    });

    const csvContent = '\uFEFF' + csvData.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `web_platform_projects_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const rows = await window.aivicApi.list(0);
      currentData = rows || tables[0]?.records || [];
      filteredData = [...currentData];
      applySorting();

      const startIndex = (currentPage - 1) * pageSize;
      const endIndex = startIndex + pageSize;
      renderRows(filteredData.slice(startIndex, endIndex));
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      currentData = tables[0]?.records || [];
      filteredData = [...currentData];
      renderRows(filteredData.slice(0, pageSize));
    }
  }

  // イベントリスナー登録

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', filterData);

  // リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#input-search').value = '';
    container.querySelector('#filter-scale').value = '';
    container.querySelector('#filter-phase').value = '';
    container.querySelector('#filter-tech').value = '';
    container.querySelector('#filter-status').value = '';
    filterData();
  });

  // ソート変更
  container.querySelector('#sort-order').addEventListener('change', filterData);

  // 表示件数変更
  container.querySelector('#page-size').addEventListener('change', (e) => {
    pageSize = parseInt(e.target.value);
    currentPage = 1;
    filterData();
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // ページネーション
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      const startIndex = (currentPage - 1) * pageSize;
      const endIndex = startIndex + pageSize;
      renderRows(filteredData.slice(startIndex, endIndex));
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredData.length / pageSize);
    if (currentPage < totalPages) {
      currentPage++;
      const startIndex = (currentPage - 1) * pageSize;
      const endIndex = startIndex + pageSize;
      renderRows(filteredData.slice(startIndex, endIndex));
    }
  });

  // 行レベル操作（編集・削除・行クリック）
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この案件を削除しますか？')) return;

      try {
        await window.aivicApi.delete(0, deleteBtn.dataset.id);
        await loadData(); // データ再読み込み
      } catch (error) {
        console.error('削除エラー:', error);
      }
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      window.showScreen('scr-3', { id: editBtn.dataset.id });
      return;
    }

    // 行クリック（詳細表示）
    const row = e.target.closest('tr[data-id]');
    if (row && row.dataset.id && !e.target.closest('button')) {
      window.showScreen('scr-3', { id: row.dataset.id });
      return;
    }
  });

  // Enter キーで検索実行
  container.querySelector('#input-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      filterData();
    }
  });

  // 初期データ読み込み実行
  loadData();
}

function(container, apiUrl, tables) {
  // タブ切り替え機能
  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabContents = container.querySelectorAll('.tab-content');

  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetTab = btn.dataset.tab;

      // すべてのタブボタンを非アクティブに
      tabButtons.forEach(b => {
        b.classList.remove('active', 'border-primary', 'text-primary');
        b.classList.add('border-transparent', 'text-muted');
      });

      // クリックされたタブボタンをアクティブに
      btn.classList.add('active', 'border-primary', 'text-primary');
      btn.classList.remove('border-transparent', 'text-muted');

      // すべてのタブコンテンツを非表示に
      tabContents.forEach(content => {
        content.classList.add('hidden');
      });

      // 対象のタブコンテンツを表示
      const targetContent = container.querySelector(`#tab-${targetTab}`);
      if (targetContent) {
        targetContent.classList.remove('hidden');
      }
    });
  });

  // 保存ボタンのイベントリスナー
  container.querySelector('[data-testid="save-button"]').addEventListener('click', async () => {
    const projectData = {
      name: container.querySelector('[data-testid="project-name-input"]').value,
      status: container.querySelector('[data-testid="status-select"]').value,
      startDate: container.querySelector('[data-testid="start-date-input"]').value,
      endDate: container.querySelector('[data-testid="end-date-input"]').value,
      budget: parseInt(container.querySelector('[data-testid="budget-input"]').value),
      manager: container.querySelector('[data-testid="manager-select"]').value,
      description: container.querySelector('[data-testid="description-input"]').value,
      frontendTech: container.querySelector('[data-testid="frontend-tech-select"]').value,
      backendTech: container.querySelector('[data-testid="backend-tech-select"]').value,
      database: container.querySelector('[data-testid="database-select"]').value,
      cloudPlatform: container.querySelector('[data-testid="cloud-platform-select"]').value,
      techRequirements: container.querySelector('[data-testid="tech-requirements-input"]').value
    };

    try {
      const result = await window.aivicApi.update(0, 1, projectData);
      if (result) {
        // 成功時の処理
        const statusDisplay = container.querySelector('[data-testid="status-display"]');
        statusDisplay.textContent = getStatusText(projectData.status);

        // 左側の表示も更新
        container.querySelector('[data-testid="project-name-display"]').textContent = projectData.name;

        alert('プロジェクト情報を更新しました');
      } else {
        alert('保存に失敗しました');
      }
    } catch (error) {
      console.error('Save error:', error);
      alert('保存中にエラーが発生しました');
    }
  });

  // キャンセルボタンのイベントリスナー
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    if (confirm('変更を破棄しますか？')) {
      window.showScreen('scr-2');
    }
  });

  // ステータステキスト変換関数
  function getStatusText(status) {
    const statusMap = {
      'planning': '計画中',
      'in-progress': '進行中',
      'testing': 'テスト中',
      'completed': '完了',
      'on-hold': '保留'
    };
    return statusMap[status] || status;
  }

  // 初期データの読み込み
  if (tables && tables[0] && tables[0].records && tables[0].records.length > 0) {
    const project = tables[0].records[0];

    // フォームに初期値を設定
    if (project.name) container.querySelector('[data-testid="project-name-input"]').value = project.name;
    if (project.status) container.querySelector('[data-testid="status-select"]').value = project.status;
    if (project.startDate) container.querySelector('[data-testid="start-date-input"]').value = project.startDate;
    if (project.endDate) container.querySelector('[data-testid="end-date-input"]').value = project.endDate;
    if (project.budget) container.querySelector('[data-testid="budget-input"]').value = project.budget;
    if (project.manager) container.querySelector('[data-testid="manager-select"]').value = project.manager;
    if (project.description) container.querySelector('[data-testid="description-input"]').value = project.description;
  }

  // フォーカス時のスタイル設定
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(34, 197, 94, 0.08)';
    });

    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(0,0,0,0.18)';
      input.style.boxShadow = 'none';
    });
  });
}
